  function renderGuide(){guideOverlay.classList.toggle('is-open',guideOpen);guideOpenButton.setAttribute('aria-expanded',String(guideOpen));guideOpenButton.disabled=busy()||guideStarting;guideBackButton.hidden=guideStep===0||guideStep>=guideSteps.length;guideNextButton.hidden=guideStep>=guideSteps.length;guideStartButton.hidden=guideStep<guideSteps.length;guideCloseButton.disabled=guideStarting;guideBackButton.disabled=guideStarting;guideNextButton.disabled=guideStarting;guideStartButton.disabled=guideStarting||busy();guideField.disabled=guideStarting;guideStartButton.textContent=guideStarting?'Starting…':'Start building';if(guideStep<guideSteps.length){const step=guideSteps[guideStep];guideEyebrow.textContent='Step '+(guideStep+1)+' of '+guideSteps.length;guideQuestion.textContent=step.question;guideHint.textContent=step.hint;guideFieldLabel.textContent=step.fieldLabel;guideField.placeholder=step.placeholder;guideField.value=guideAnswers[guideStep]||'';guideField.hidden=false;guideChoices.hidden=false;guideReview.hidden=true;guideNextButton.textContent=guideStep===guideSteps.length-1?'Review brief':'Continue';renderGuideChoices(guideStep);}else{guideEyebrow.textContent='Review your brief';guideQuestion.textContent='Anything else to add before we start?';guideHint.textContent='Review your answers, add any final details, or go back to change a choice.';guideFieldLabel.textContent='Final additions (optional)';guideField.placeholder='Add any final instructions, constraints, or ideas here (optional).';guideField.value=guideFinalNotes;guideField.hidden=false;guideChoices.hidden=true;guideReview.hidden=false;guideReview.textContent=guideAnswers.map((answer,index)=>{const selected=summarizeChoices(index);return guideSteps[index].question+'\n'+(selected?'Selected: '+selected+'\n':'')+(answer.trim()||'No additional detail.')}).join('\n\n');}}
