  async function startGuidedBuild(){if(guideStarting||busy())return;if(!options.submitBrief){guideError.textContent='The Design Studio conversation is unavailable.';return;}guideStarting=true;renderGuide();const headings=['App idea','Users and goals','Target platform and coding approach','Must-have features','Language and look','Data and integrations'];const sections=guideAnswers.map((answer,index)=>headings[index]+':\nSelected choices: '+(summarizeChoices(index)||'No preference specified.')+'\n'+(answer.trim()||'No additional detail.')).join('\n\n');const brief='Build a complete first version of the application described below in my selected Design Studio project. Inspect the existing files and preserve the project’s current framework and conventions. Implement the working app, not just a plan or mockup. Use sensible defaults for unspecified optional details, make the interface responsive, and include clear loading, empty, and error states where relevant. Ask me a short follow-up only if a missing detail blocks implementation. When finished, run the app in the Design Studio preview if its existing setup supports it.\n\n'+sections+'\n\nAdditional requirements:\n'+(guideFinalNotes.trim()||'None.');try{const accepted=await options.submitBrief(brief);if(accepted){guideOpen=false;guideStep=0;guideAnswers=['','','','','',''];guideFinalNotes='';guideSelections={appType:[],platform:[],stack:[],audience:[],features:[],uiLanguage:[],uiStyle:[],data:[]};guideError.textContent='';}else guideError.textContent='Muse is busy. Wait for the current task to finish, then try again.';}catch(e:any){guideError.textContent=e?.message||'Muse could not start the build.';}finally{guideStarting=false;renderGuide();}}
